#!/usr/bin/env python3
"""
笑话生成器 - 生成适合日常分享的幽默笑话
"""

jokes = [
    "为什么程序员总是分不清万圣节和圣诞节？因为 Oct 31 == Dec 25！",
    "小明问爸爸：'爸爸，我是不是傻孩子？' 爸爸说：'傻孩子，你怎么会是傻孩子呢？'。"
]

def generate_joke():
    import random
    return random.choice(jokes)

if __name__ == "__main__":
    joke = generate_joke()
    print(f"✨ 今日份笑话：{joke}")
    print(f"字数：{len(joke)}")

